public static void binarySearch(int x) {
    int arr[] = {2, 3, 4, 10, 40};
    int l = 0, r = arr.length - 1;
    while (l <= r) {
      int m = l + (r - l) / 2;
      if (arr[m] == x) return;
      if (arr[m] < x) l = m + 1;
      else r = m - 1;
    }
    assert false;
  }

