public static int normalizedDistance(int x, int y) {
    int dst = y - x;
    if (dst == 0) {
      return 0;
    }
    if (x < 0) x = -x;
    if (y < 0) y = -y;
    if (x >= y) {
      return dst / x;
    } else {
      return dst / y;
    }
  }

public static int badNormalizedDistance(int x, int y) {
